function renderIntel(ui){const root=ui?.q?.('villageContent'),v=ui?.world?.selectedNation;if(!root||!v||ui.sub!=='military')return;root.querySelectorAll('.v33e-intel-panel,.v33e2-intel-panel').forEach(x=>x.remove());const x=currentIntent(ui.world,v.id),target=x?village(ui.world,x.targetId):null,pic=target?readOnlyPicture(v,target,ui.world):null,state=ensure(ui.world),recon=x?state.reconByIntent[String(x.id)]:null,box=document.createElement('div');box.className='v33e-intel-panel v33e2-intel-panel';const intentHtml=x?`<div class="v33e-intent"><b>${esc(v.name)} → ${esc(target?.name||'#'+x.targetId)}</b><br><span class="muted">평가 ${Number(x.score||0).toFixed(1)} · 판단 전력비 ${Number(x.estimatedAdvantage||0).toFixed(2)} · 군사 신뢰 ${(Number(pic?.confidence?.military||x.intelConfidence||0)*100).toFixed(0)}% · ${Number(pic?.ageDays??x.intelAgeDays33E??0).toFixed(0)}일 전 · ${esc(pic?.source||x.intelSource33E||'UNKNOWN')} · RECON ${esc(recon?.lastResult||'대기')}</span>${pic?`<br><span class="muted">적 야전 중심 <b>${pic.military.fieldCenter}</b> · 범위 <b>${pic.military.minField}~${pic.military.maxField}</b> · 전략 판단값 <b>${pic.military.fieldPlanning}</b> · 위험가중 ${(pic.riskWeight*100).toFixed(0)}%</span>`:''}</div>`:'<div class="small muted">현재 활성 공격 검토 없음. UI 조회는 정보상태를 갱신하지 않습니다.</div>';const rows=(ui.world.activeVillages||[]).filter(t=>t.id!==v.id).map(t=>({t,p:readOnlyPicture(v,t,ui.world)})).sort((a,b)=>Number(b.t.id===x?.targetId)-Number(a.t.id===x?.targetId)||Number(b.p?.confidence?.military||0)-Number(a.p?.confidence?.military||0));box.innerHTML=`<div class="section-head"><div><strong>🕵 V0.33E2 정보·정찰 V2</strong><div class="small muted">관측 중심값 + 시간에 따라 확장되는 추정범위 → 성향별 위험가중 판단 → War Intent / D2 준비</div></div><span class="tag">${x?phaseLabel(x.phase):'INTEL V2'}</span></div>${intentHtml}<div class="v33e-intel-list">${rows.map(({t,p})=>!p?`<div><b>${esc(t.name)}</b><span class="muted">정보 없음</span></div>`:`<div><b>${esc(t.name)}</b><span>야전 <strong>${p.military.fieldCenter}</strong> <small>(${p.military.minField}~${p.military.maxField})</small> · 판단 ${p.military.fieldPlanning}</span><span>신뢰 ${(p.confidence.military*100).toFixed(0)}%</span><span>${p.ageDays.toFixed(0)}일 전</span><span class="muted">${esc(p.source)} · ${freshness(p)}</span></div>`).join('')}</div>`;root.insertAdjacentElement('afterbegin',box);const d2=root.querySelector('.v33d2-panel');if(d2){const small=d2.querySelector('.section-head .small.muted');if(small)small.textContent='World Truth → Intelligence E2 추정범위 → War Intent → 실제 동원·비축·집결·인프라 준비';}}
if(NS.UI){const setPrev=NS.UI.prototype.setWorld,headPrev=NS.UI.prototype.renderHeader,contentPrev=NS.UI.prototype.renderVillageContent,codexPrev=NS.UI.prototype.renderCodex;NS.UI.prototype.setWorld=function(w){return setPrev.call(this,attach(w));};NS.UI.prototype.renderHeader=function(){const r=headPrev.call(this);document.title='Village Observer V0.33E2F';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33E2F</strong>';const st=this.q?.('runtimeStatus');if(st){const s=ensure(this.world),pairs=[];for(const a of this.world.activeVillages||[])for(const t of this.world.activeVillages||[])if(a.id!==t.id){const p=readOnlyPicture(a,t,this.world);if(p)pairs.push(p);}const width=pairs.length?(pairs.reduce((z,p)=>z+Number(p.military.rangeWidth||0),0)/pairs.length):0;st.textContent=`✓ V0.33E2F 정보 불확실성·능동정찰 · 평균 야전범위 폭 ${width.toFixed(1)} · RECON ${s.stats.reconSuccesses}/${s.stats.reconAttempts} · 개전 Intel ${s.stats.declarationSnapshots}`;}return r;};NS.UI.prototype.renderVillageContent=function(){const r=contentPrev.call(this);renderIntel(this);return r;};NS.UI.prototype.renderCodex=function(){const r=codexPrev.call(this),el=this.q?.('codexContent');if(el&&!el.querySelector('.v33e2-note')){const note=document.createElement('div');note.className='codex-note v33e2-note';note.innerHTML='<strong>V0.33E2 Intelligence Uncertainty & Reconnaissance V2</strong><br>국가 AI는 적 병력을 하나의 확정 숫자가 아니라 관측 중심값과 하한·상한 범위로 기억합니다. 정보가 낡으면 범위가 넓어지고, 생존안정형·외교형은 범위의 높은 쪽을 더 보수적으로, 영토확장형은 중심값에 더 가깝게 사용합니다. 활성 War Intent는 정보가 낡거나 범위가 넓을 때 국경·파수망·접촉망을 통해 능동 정찰을 시도합니다. 정보는 전투력 보너스를 직접 주지 않습니다.';(el.querySelector('[data-page="war"]')||el).insertAdjacentElement('afterbegin',note);}return r;};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33e2-intel-panel{border-color:rgba(120,190,245,.48);background:rgba(55,105,165,.09)}.v33e2-intel-panel .v33e-intent b{color:#eef6ff}`;document.head.appendChild(st);}
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33E2F'))NS.PATCH_NOTES.unshift({version:'V0.33E2F',date:'2026-10-01',title:'Intel Renderer Ownership Hotfix',summary:'군사 탭에서 E2 정보·정찰 V2 패널이 구형 V0.33E INTEL V1 렌더러에 의해 다시 덮어써지는 회귀를 수정합니다. E2 활성화 이후 구형 Intel writer는 실행되지 않으며 D2 설명도 E2 추정범위 기준으로 고정됩니다.',sections:[['Intel UI 단일 소유권',['V0.33E의 renderIntelE는 V0.33E2가 활성화된 뒤 즉시 no-op 처리됩니다.','구형 E renderVillageContent/render 후처리도 E2 활성화 시 Intel V1 writer를 호출하지 않습니다.','최종 군사 탭 Intelligence panel writer는 E2 renderIntel 하나만 남습니다.']],['D2 문구 수정',['STANDBY 상태에서도 기존 Intelligence 100% 정확 proxy 문구를 노출하지 않습니다.','D2 설명은 World Truth → Intelligence E2 추정범위 → War Intent → 실제 준비 흐름으로 항상 동기화됩니다.']],['시뮬레이션 규칙 유지',['Intelligence 추정범위·RECON·War Intent/D2 planning·Commander·전투·점령·피로도·기술 비용과 Knowledge 생산은 V0.33E2 그대로입니다.']]]});
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33E2'))NS.PATCH_NOTES.unshift({version:'V0.33E2',date:'2026-10-01',title:'Intelligence Uncertainty & Reconnaissance V2',summary:'E1 자연주행에서 War Intent 적 야전병력 추정 111건 중 109건이 실제값과 같았던 문제를 겨냥합니다. 군사정보를 중심값+범위로 바꾸고 정보 노후화에 따라 범위를 확장하며, 활성 War Intent가 실제 정찰 경로를 통해 정보를 갱신할 수 있게 합니다.',sections:[['추정범위 V2',['야전병력·총군사력·동원가능 인구·Readiness를 중심값과 하한/상한으로 저장합니다.','관측 이후 시간이 지나면 중심값은 그대로 유지되지만 범위가 점차 넓어져 stale information의 불확실성을 실제 판단에 반영합니다.','소규모 Formation도 낮은 신뢰도에서는 0↔1명 또는 ±1명 이상 오판할 수 있어 정수 반올림으로 완전정보에 수렴하던 문제를 줄입니다.']],['성향별 위험 해석',['생존안정형·외교형은 적 전력 범위 상단을 더 크게 반영하고, 영토확장형은 중심값에 더 가깝게 판단합니다.','D1 전력비와 D2 enemyPotential/fieldGoal/eligible 목표가 이 risk-weighted planning 값을 사용합니다.','정보 불확실성은 직접 전투 보너스나 패널티를 만들지 않습니다.']],['능동 정찰 V1',['활성 War Intent에서 군사 신뢰도가 낮거나, 150일 이상 낡았거나, 야전병력 범위 폭이 3 이상이면 90일 cadence로 RECON을 검토합니다.','직접 국경은 BORDER_RECON, 파수망+접촉은 WATCHTOWER_RECON, 교역/고급 접촉은 NETWORK_RECON을 사용합니다.','정찰은 synthetic Person을 만들지 않고 접근 경로가 없으면 실패 이벤트만 남깁니다.']],['개전 정보 Snapshot',['AI 선전포고 순간 공격국이 알고 있던 야전병력 중심값·범위·전략 판단값·신뢰도·정보나이와 debug-only 실제값을 전쟁 객체와 DECLARATION_INTEL_SNAPSHOT33E2에 저장합니다.','CSV에서 개전 정보 평균 절대오차, 범위 이탈 횟수, 2명 이상 중대 오판 수를 장기주행 비교할 수 있습니다.']],['Observer Effect 제거',['군사정보 UI를 열거나 telemetry snapshot/CSV를 생성하는 행위는 더 이상 정보 관측을 갱신하지 않습니다.','정보 갱신은 passive observation cadence와 실제 RECON 이벤트에서만 발생합니다.']],['전술정보 경계 강화',['적 Formation 위치·병력 조회는 last-seen proxy를 사용하고, 전술 방어 전력 계산에서도 live enemy cohort membership을 직접 읽지 않습니다.','E2는 여전히 플레이어 지도 Fog of War, Spy Person, 허위정보/기만작전까지는 도입하지 않습니다.']],['E1 기준 유지',['32개 기술/총 4,815 Knowledge, Knowledge 생산 ×1.00, Formation Commander, small-unit casualty guard, War History single writer, War Chest·Final Commitment·전투·점령·피로도 규칙은 그대로 유지합니다.']]]});
